public struct InputEventPayload {
    public let type: InputEventType
    public let x: Float
    public let y: Float
    public let keyCode: UInt16
    public let modifiers: ModifierFlags
    public let scrollDeltaX: Float
    public let scrollDeltaY: Float

    public static let size = 21

    public init(type: InputEventType, x: Float, y: Float, keyCode: UInt16 = 0,
                modifiers: ModifierFlags = [], scrollDeltaX: Float = 0, scrollDeltaY: Float = 0) {
        self.type = type; self.x = x; self.y = y; self.keyCode = keyCode
        self.modifiers = modifiers; self.scrollDeltaX = scrollDeltaX; self.scrollDeltaY = scrollDeltaY
    }

    public func serialize() -> Data {
        var d = Data(capacity: InputEventPayload.size)
        var t = type.rawValue; d.append(Data(bytes: &t, count: 1))
        var fx = x.bitPattern.littleEndian; d.append(Data(bytes: &fx, count: 4))
        var fy = y.bitPattern.littleEndian; d.append(Data(bytes: &fy, count: 4))
        var kc = keyCode.littleEndian; d.append(Data(bytes: &kc, count: 2))
        var mf = modifiers.rawValue.littleEndian; d.append(Data(bytes: &mf, count: 2))
        var sdx = scrollDeltaX.bitPattern.littleEndian; d.append(Data(bytes: &sdx, count: 4))
        var sdy = scrollDeltaY.bitPattern.littleEndian; d.append(Data(bytes: &sdy, count: 4))
        return d
    }

    public static func deserialize(from data: Data) -> InputEventPayload? {
        guard data.count >= size else { return nil }
        guard let t = InputEventType(rawValue: data[0]) else { return nil }
        let x = Float(bitPattern: data.subdata(in: 1..<5).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian })
        let y = Float(bitPattern: data.subdata(in: 5..<9).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian })
        let kc = data.subdata(in: 9..<11).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian }
        let mf = ModifierFlags(rawValue: data.subdata(in: 11..<13).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian })
        let sdx = Float(bitPattern: data.subdata(in: 13..<17).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian })
        let sdy = Float(bitPattern: data.subdata(in: 17..<21).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian })
        return InputEventPayload(type: t, x: x, y: y, keyCode: kc, modifiers: mf, scrollDeltaX: sdx, scrollDeltaY: sdy)
    }
}

import Foundation

public enum ControlMessageType: UInt8 {
    case requestKeyFrame = 0
    case startStream = 1
    case stopStream = 2
    case disconnect = 3
    case ping = 4
    case pong = 5
    case bitrateAdjust = 6
    case streamConfigRequest = 7
    case streamConfigResponse = 8
    case streamConfigReject = 9
    case streamConfigError = 10
    case clipboardSyncRequest = 11
    case clipboardSyncUpdate = 12
    case clipboardSyncError = 13
}

public struct ControlMessage {
    public let type: ControlMessageType
    public let payload: Data?

    public init(type: ControlMessageType, payload: Data? = nil) {
        self.type = type
        self.payload = payload
    }

    public func serialize() -> Data {
        var d = Data([type.rawValue])
        if let payload = payload {
            d.append(payload)
        }
        return d
    }

    public static func deserialize(from data: Data) -> ControlMessage? {
        guard data.count >= 1, let t = ControlMessageType(rawValue: data[0]) else { return nil }
        let payload: Data? = data.count > 1 ? data.subdata(in: 1..<data.count) : nil
        return ControlMessage(type: t, payload: payload)
    }
}

public struct BitrateAdjustPayload {
    public let targetBitrate: Int32

    public static let size = 4

    public init(targetBitrate: Int32) {
        self.targetBitrate = targetBitrate
    }

    public func serialize() -> Data {
        var d = Data(capacity: BitrateAdjustPayload.size)
        var br = targetBitrate.littleEndian
        d.append(Data(bytes: &br, count: 4))
        return d
    }

    public static func deserialize(from data: Data) -> BitrateAdjustPayload? {
        guard data.count >= size else { return nil }
        let br = data.withUnsafeBytes { $0.load(as: Int32.self).littleEndian }
        return BitrateAdjustPayload(targetBitrate: br)
    }
}

public struct CursorUpdate {
    public let x: Float
    public let y: Float
    public let cursorType: UInt8

    public static let size = 9

    public init(x: Float, y: Float, cursorType: UInt8 = 0) {
        self.x = x; self.y = y; self.cursorType = cursorType
    }

    public func serialize() -> Data {
        var d = Data(capacity: CursorUpdate.size)
        var fx = x.bitPattern.littleEndian; d.append(Data(bytes: &fx, count: 4))
        var fy = y.bitPattern.littleEndian; d.append(Data(bytes: &fy, count: 4))
        var ct = cursorType; d.append(Data(bytes: &ct, count: 1))
        return d
    }

    public static func deserialize(from data: Data) -> CursorUpdate? {
        guard data.count >= size else { return nil }
        let x = Float(bitPattern: data.subdata(in: 0..<4).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian })
        let y = Float(bitPattern: data.subdata(in: 4..<8).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian })
        return CursorUpdate(x: x, y: y, cursorType: data[8])
    }
}

public class AtomicBool {
    private let lock = NSLock()
    private var _value: Bool

    public init(_ value: Bool = false) { _value = value }

    public var value: Bool {
        get { lock.lock(); defer { lock.unlock() }; return _value }
        set { lock.lock(); defer { lock.unlock() }; _value = newValue }
    }
}

import Foundation

public class FrameReceiver {
    private struct FrameAssembly {
        let header: FrameHeaderPayload
        var chunks: [UInt16: Data]
        let startTime: Date

        var isComplete: Bool { chunks.count == Int(header.totalChunks) }

        func assemble() -> Data? {
            guard isComplete else { return nil }
            var result = Data(capacity: Int(header.totalSize))
            for i in 0..<header.totalChunks {
                guard let chunk = chunks[i] else { return nil }
                result.append(chunk)
            }
            return result
        }
    }

    private struct LossEntry {
        let timestamp: Date
        let lost: Int
        let total: Int
    }

    private var frames: [UInt32: FrameAssembly] = [:]
    private let assemblyQueue = DispatchQueue(label: "eclipticrd.frame-assembly", qos: .userInteractive)
    private var cleanupTimer: DispatchSourceTimer?
    private let timeout: Double = ERDConstants.frameAssemblyTimeout

    private var expectedFrameId: UInt32 = 0
    private var hasReceivedFirstFrame = false
    private var lossEntries: [LossEntry] = []
    private let lossLock = NSLock()

    private var completedFrameTimestamps: [Date] = []
    public private(set) var totalFramesReceived: Int = 0

    public var onFrameReady: ((Data, FrameHeaderPayload) -> Void)?
    public var onCursorUpdate: ((CursorUpdate) -> Void)?

    /// Computed property: FPS based on frames completed in the last 1 second
    public var recentFPS: Double {
        assemblyQueue.sync {
            let cutoff = Date().addingTimeInterval(-1.0)
            let recentCount = completedFrameTimestamps.filter { $0 > cutoff }.count
            return Double(recentCount)
        }
    }

    public var frameLossRatio: Double {
        lossLock.lock()
        defer { lossLock.unlock() }
        let cutoff = Date().addingTimeInterval(-5.0)
        let recent = lossEntries.filter { $0.timestamp > cutoff }
        let totalLost = recent.reduce(0) { $0 + $1.lost }
        let totalFrames = recent.reduce(0) { $0 + $1.total }
        guard totalFrames > 0 else { return 0.0 }
        return Double(totalLost) / Double(totalFrames)
    }

    public init() {
        startCleanupTimer()
    }

    deinit {
        let timer = cleanupTimer
        assemblyQueue.async {
            timer?.cancel()
        }
    }

    public func stop() {
        assemblyQueue.sync {
            self.cleanupTimer?.cancel()
            self.cleanupTimer = nil
            self.frames.removeAll()
            self.completedFrameTimestamps.removeAll()
            self.totalFramesReceived = 0
            self.expectedFrameId = 0
            self.startCleanupTimer()
        }
        lossLock.lock()
        lossEntries.removeAll()
        hasReceivedFirstFrame = false
        lossLock.unlock()
    }

    public func handlePacket(_ data: Data) {
        guard data.count >= ERDConstants.packetHeaderSize else { return }
        guard let header = PacketHeader.deserialize(from: data) else { return }
        let payload = data.subdata(in: ERDConstants.packetHeaderSize..<data.count)

        assemblyQueue.async { [weak self] in
            switch header.type {
            case .frameHeader:
                self?.handleFrameHeader(payload)
            case .frameChunk:
                self?.handleFrameChunk(payload)
            case .cursorUpdate:
                if let cursor = CursorUpdate.deserialize(from: payload) {
                    self?.onCursorUpdate?(cursor)
                }
            default: break
            }
        }
    }

    private func handleFrameHeader(_ data: Data) {
        guard let fh = FrameHeaderPayload.deserialize(from: data) else {
            ERDLog.error("[FrameReceiver] Failed to deserialize frame header from \(data.count) bytes")
            return
        }

        if fh.isKeyFrame {
            let keysToRemove = frames.keys.filter { $0 < fh.frameId }
            for key in keysToRemove {
                if let assembly = frames[key], !assembly.isComplete {
                    frames.removeValue(forKey: key)
                }
            }
        }

        trackFrameLoss(receivedFrameId: fh.frameId)
        frames[fh.frameId] = FrameAssembly(header: fh, chunks: [:], startTime: Date())
    }

    private func handleFrameChunk(_ data: Data) {
        guard let chunk = FrameChunkPayload.deserialize(from: data) else {
            ERDLog.error("[FrameReceiver] Failed to deserialize chunk from \(data.count) bytes")
            return
        }
        guard frames[chunk.frameId] != nil else {
            ERDLog.debug("[FrameReceiver] Orphan chunk: frame#\(chunk.frameId) idx=\(chunk.chunkIndex) (no header yet)")
            return
        }

        frames[chunk.frameId]!.chunks[chunk.chunkIndex] = chunk.chunkData
        let assembly = frames[chunk.frameId]!

        if assembly.isComplete {
            let completed = frames.removeValue(forKey: chunk.frameId)!
            if let frameData = completed.assemble() {
                ERDLog.video("[FrameReceiver] ✅ Frame #\(chunk.frameId) assembled: \(frameData.count) bytes")
                totalFramesReceived += 1
                completedFrameTimestamps.append(Date())
                let cutoff = Date().addingTimeInterval(-2.0)
                completedFrameTimestamps.removeAll { $0 < cutoff }
                onFrameReady?(frameData, completed.header)
            }
        }
    }

    private func trackFrameLoss(receivedFrameId: UInt32) {
        lossLock.lock()
        defer { lossLock.unlock() }

        if !hasReceivedFirstFrame {
            hasReceivedFirstFrame = true
            expectedFrameId = receivedFrameId + 1
            lossEntries.append(LossEntry(timestamp: Date(), lost: 0, total: 1))
            return
        }

        let gap = receivedFrameId > expectedFrameId ? Int(receivedFrameId - expectedFrameId) : 0
        lossEntries.append(LossEntry(timestamp: Date(), lost: gap, total: 1 + gap))
        expectedFrameId = receivedFrameId + 1

        let cutoff = Date().addingTimeInterval(-10.0)
        lossEntries.removeAll { $0.timestamp < cutoff }
    }

    private func startCleanupTimer() {
        let timer = DispatchSource.makeTimerSource(queue: assemblyQueue)
        timer.schedule(deadline: .now() + 1.0, repeating: 1.0)
        timer.setEventHandler { [weak self] in
            guard let self = self else { return }
            let now = Date()
            self.frames = self.frames.filter { now.timeIntervalSince($0.value.startTime) < self.timeout }
        }
        timer.resume()
        cleanupTimer = timer
    }
}

import Foundation

public class FrameSender {
    private let udpChannel: UDPChannel
    private var frameIdCounter: UInt32 = 0
    private let counterLock = NSLock()

    public init(udpChannel: UDPChannel) {
        self.udpChannel = udpChannel
    }

    public func sendFrame(data: Data, width: Int, height: Int, isKeyFrame: Bool) {
        counterLock.lock()
        frameIdCounter += 1
        let frameId = frameIdCounter
        counterLock.unlock()

        let maxPayload = ERDConstants.maxPayloadSize - FrameChunkPayload.headerSize
        let totalChunks = UInt16((data.count + maxPayload - 1) / maxPayload)

        guard totalChunks <= ERDConstants.maxChunksPerFrame else {
            ERDLog.error("[FrameSender] Frame too large: \(data.count) bytes, \(totalChunks) chunks")
            return
        }

        // 1. Send frame header via UDP
        let header = FrameHeaderPayload(
            frameId: frameId, width: UInt16(width), height: UInt16(height),
            isKeyFrame: isKeyFrame, totalChunks: totalChunks, totalSize: UInt32(data.count)
        )
        udpChannel.sendPacket(type: .frameHeader, payload: header.serialize())

        // 2. Send frame chunks via UDP
        var offset = 0
        var chunkIndex: UInt16 = 0
        while offset < data.count {
            let end = min(offset + maxPayload, data.count)
            let chunkData = data.subdata(in: offset..<end)
            let chunk = FrameChunkPayload(frameId: frameId, chunkIndex: chunkIndex, chunkData: chunkData)
            udpChannel.sendPacket(type: .frameChunk, payload: chunk.serialize())
            offset = end
            chunkIndex += 1
        }
    }

    public func sendCursorUpdate(x: Float, y: Float, cursorType: UInt8 = 0) {
        let cursor = CursorUpdate(x: x, y: y, cursorType: cursorType)
        udpChannel.sendPacket(type: .cursorUpdate, payload: cursor.serialize())
    }
}

import Foundation
import VideoToolbox
import CoreMedia

public class VideoDecoder {
    private var session: VTDecompressionSession?
    private var formatDescription: CMVideoFormatDescription?
    private let decoderQueue = DispatchQueue(label: "eclipticrd.decoder", qos: .userInteractive)
    private var retainedSelf: Unmanaged<VideoDecoder>?

    private var sps: Data?
    private var pps: Data?
    private var vps: Data?

    public var onDecodedFrame: ((CVPixelBuffer) -> Void)?

    public init() {}

    // NOTE: Do not call stop() from deinit — decoderQueue.sync would deadlock
    // if the last reference is released on decoderQueue itself.
    // Callers must call stop() explicitly before releasing.

    public func decode(_ data: Data) {
        decoderQueue.async { [weak self] in
            guard let self = self else { return }
            self.processNALUs(data)
        }
    }

    public func stop() {
        decoderQueue.sync {
            if let session = self.session {
                VTDecompressionSessionInvalidate(session)
                self.session = nil
            }
            self.retainedSelf?.release()
            self.retainedSelf = nil
            self.formatDescription = nil
            self.sps = nil; self.pps = nil; self.vps = nil
        }
    }

    private func processNALUs(_ data: Data) {
        // HEVC NALUs use 4-byte length prefix (AVCC format from VideoToolbox output)
        var offset = 0
        while offset + 4 <= data.count {
            let naluLength = data.subdata(in: offset..<offset+4).withUnsafeBytes { $0.load(as: UInt32.self).bigEndian }
            offset += 4
            guard naluLength > 0, offset + Int(naluLength) <= data.count else { break }

            let nalu = data.subdata(in: offset..<offset+Int(naluLength))
            let naluType = (nalu[0] >> 1) & 0x3F // HEVC NAL unit type

            switch naluType {
            case 32: // VPS
                vps = nalu
            case 33: // SPS
                sps = nalu
            case 34: // PPS
                pps = nalu
                createDecoderIfNeeded()
            default:
                // IDR (19, 20) or non-IDR (0, 1) - decode it
                if naluType <= 31 || naluType == 19 || naluType == 20 {
                    decodeNALU(nalu)
                }
            }
            offset += Int(naluLength)
        }
    }

    private func createDecoderIfNeeded() {
        guard let vps = vps, let sps = sps, let pps = pps else { return }

        // Nest withUnsafeBytes calls to keep pointers valid for the entire scope.
        var newFormat: CMVideoFormatDescription?
        vps.withUnsafeBytes { vpsBuffer in
            sps.withUnsafeBytes { spsBuffer in
                pps.withUnsafeBytes { ppsBuffer in
                    let pointers: [UnsafePointer<UInt8>] = [
                        vpsBuffer.baseAddress!.assumingMemoryBound(to: UInt8.self),
                        spsBuffer.baseAddress!.assumingMemoryBound(to: UInt8.self),
                        ppsBuffer.baseAddress!.assumingMemoryBound(to: UInt8.self)
                    ]
                    let sizes = [vps.count, sps.count, pps.count]

                    CMVideoFormatDescriptionCreateFromHEVCParameterSets(
                        allocator: kCFAllocatorDefault,
                        parameterSetCount: 3,
                        parameterSetPointers: pointers,
                        parameterSetSizes: sizes,
                        nalUnitHeaderLength: 4,
                        extensions: nil,
                        formatDescriptionOut: &newFormat
                    )
                }
            }
        }

        guard let format = newFormat else { return }

        if session != nil {
            VTDecompressionSessionInvalidate(session!)
            session = nil
        }
        retainedSelf?.release()
        retainedSelf = Unmanaged.passRetained(self)
        formatDescription = format

        let pixelBufferAttributes: [String: Any] = [
            kCVPixelBufferPixelFormatTypeKey as String: kCVPixelFormatType_32BGRA,
            kCVPixelBufferMetalCompatibilityKey as String: true
        ]

        var callbackRecord = VTDecompressionOutputCallbackRecord(
            decompressionOutputCallback: decoderCallback,
            decompressionOutputRefCon: retainedSelf!.toOpaque()
        )

        VTDecompressionSessionCreate(
            allocator: kCFAllocatorDefault,
            formatDescription: format,
            decoderSpecification: nil,
            imageBufferAttributes: pixelBufferAttributes as CFDictionary,
            outputCallback: &callbackRecord,
            decompressionSessionOut: &session
        )
    }

    private func decodeNALU(_ nalu: Data) {
        guard let session = session, let format = formatDescription else { return }

        // Wrap NALU with 4-byte length prefix
        var length = UInt32(nalu.count).bigEndian
        var blockData = Data(bytes: &length, count: 4)
        blockData.append(nalu)

        var blockBuffer: CMBlockBuffer?
        let totalLength = blockData.count

        blockData.withUnsafeBytes { rawBuffer in
            guard let baseAddress = rawBuffer.baseAddress else { return }
            CMBlockBufferCreateWithMemoryBlock(
                allocator: kCFAllocatorDefault,
                memoryBlock: nil, blockLength: totalLength,
                blockAllocator: nil, customBlockSource: nil,
                offsetToData: 0, dataLength: totalLength,
                flags: 0, blockBufferOut: &blockBuffer)

            if let block = blockBuffer {
                CMBlockBufferReplaceDataBytes(with: baseAddress, blockBuffer: block, offsetIntoDestination: 0, dataLength: totalLength)
            }
        }

        guard let block = blockBuffer else { return }

        var sampleBuffer: CMSampleBuffer?
        var sizeArray = [totalLength]
        CMSampleBufferCreateReady(
            allocator: kCFAllocatorDefault,
            dataBuffer: block, formatDescription: format,
            sampleCount: 1, sampleTimingEntryCount: 0, sampleTimingArray: nil,
            sampleSizeEntryCount: 1, sampleSizeArray: &sizeArray,
            sampleBufferOut: &sampleBuffer)

        guard let buffer = sampleBuffer else { return }

        var flagsOut = VTDecodeInfoFlags()
        VTDecompressionSessionDecodeFrame(session, sampleBuffer: buffer, flags: [], frameRefcon: nil, infoFlagsOut: &flagsOut)
    }

    fileprivate func frameDecoded(_ imageBuffer: CVImageBuffer) {
        onDecodedFrame?(imageBuffer)
    }
}

private func decoderCallback(decompressionOutputRefCon: UnsafeMutableRawPointer?,
                              sourceFrameRefCon: UnsafeMutableRawPointer?,
                              status: OSStatus,
                              infoFlags: VTDecodeInfoFlags,
                              imageBuffer: CVImageBuffer?,
                              presentationTimeStamp: CMTime,
                              presentationDuration: CMTime) {
    guard status == noErr, let buffer = imageBuffer, let refcon = decompressionOutputRefCon else { return }
    let decoder = Unmanaged<VideoDecoder>.fromOpaque(refcon).takeUnretainedValue()
    decoder.frameDecoded(buffer)
}

import Foundation
import VideoToolbox
import CoreMedia

public enum VideoEncoderError: Error {
    case sessionCreationFailed
    case encodingFailed
}

public class VideoEncoder {
    private var session: VTCompressionSession?
    private let encoderQueue = DispatchQueue(label: "eclipticrd.encoder", qos: .userInteractive)
    private static let queueKey = DispatchSpecificKey<Bool>()
    private var frameCount: Int64 = 0
    private var retainedSelf: Unmanaged<VideoEncoder>?

    private let width: Int
    private let height: Int
    private let bitrate: Int
    private let fps: Int
    private var pendingForceKeyFrame = AtomicBool(false)

    public var onEncodedFrame: ((Data, Bool) -> Void)?

    public init(width: Int, height: Int, bitrate: Int = ERDConstants.defaultBitrate, fps: Int = ERDConstants.defaultFPS) {
        self.width = width; self.height = height; self.bitrate = bitrate; self.fps = fps
        encoderQueue.setSpecific(key: Self.queueKey, value: true)
    }

    deinit { stop() }

    public func start() throws {
        retainedSelf = Unmanaged.passRetained(self)

        let err = VTCompressionSessionCreate(
            allocator: kCFAllocatorDefault,
            width: Int32(width), height: Int32(height),
            codecType: kCMVideoCodecType_HEVC,
            encoderSpecification: nil, imageBufferAttributes: nil, compressedDataAllocator: nil,
            outputCallback: encoderCallback,
            refcon: retainedSelf!.toOpaque(),
            compressionSessionOut: &session
        )
        guard err == noErr, let session = session else { throw VideoEncoderError.sessionCreationFailed }

        VTSessionSetProperty(session, key: kVTCompressionPropertyKey_RealTime, value: kCFBooleanTrue)
        VTSessionSetProperty(session, key: kVTCompressionPropertyKey_AllowFrameReordering, value: kCFBooleanFalse)
        VTSessionSetProperty(session, key: kVTCompressionPropertyKey_AverageBitRate, value: bitrate as CFTypeRef)
        VTSessionSetProperty(session, key: kVTCompressionPropertyKey_MaxKeyFrameInterval, value: ERDConstants.keyFrameInterval as CFTypeRef)
        VTSessionSetProperty(session, key: kVTCompressionPropertyKey_ExpectedFrameRate, value: fps as CFTypeRef)
        VTSessionSetProperty(session, key: kVTCompressionPropertyKey_ProfileLevel, value: kVTProfileLevel_HEVC_Main_AutoLevel)

        VTCompressionSessionPrepareToEncodeFrames(session)
        ERDLog.video("[Encoder] Started: H.265 \(width)x\(height) @\(bitrate/1_000_000)Mbps")
    }

    public func stop() {
        let work = {
            if let session = self.session {
                VTCompressionSessionInvalidate(session)
                self.session = nil
            }
            self.retainedSelf?.release()
            self.retainedSelf = nil
            self.frameCount = 0
            ERDLog.video("[Encoder] Stopped")
        }

        if DispatchQueue.getSpecific(key: Self.queueKey) == true {
            work()
        } else {
            encoderQueue.sync { work() }
        }
    }

    public func encode(_ sampleBuffer: CMSampleBuffer) {
        encoderQueue.async { [weak self] in
            guard let self = self else { return }
            guard let session = self.session else { return }
            guard let imageBuffer = CMSampleBufferGetImageBuffer(sampleBuffer) else {
                return
            }
            let pts = CMTime(value: self.frameCount, timescale: CMTimeScale(self.fps))
            self.frameCount += 1

            var frameProps: CFDictionary? = nil
            if self.pendingForceKeyFrame.value {
                self.pendingForceKeyFrame.value = false
                frameProps = [kVTEncodeFrameOptionKey_ForceKeyFrame: true] as CFDictionary
            }

            VTCompressionSessionEncodeFrame(session, imageBuffer: imageBuffer, presentationTimeStamp: pts,
                                            duration: .invalid, frameProperties: frameProps, sourceFrameRefcon: nil, infoFlagsOut: nil)
        }
    }

    public func forceKeyFrame() {
        pendingForceKeyFrame.value = true
    }

    public func updateBitrate(_ newBitrate: Int) {
        encoderQueue.async { [weak self] in
            guard let self = self, let session = self.session else { return }
            VTSessionSetProperty(session, key: kVTCompressionPropertyKey_AverageBitRate, value: newBitrate as CFTypeRef)
        }
    }

    public func updateFPS(_ newFPS: Int) {
        encoderQueue.async { [weak self] in
            guard let self = self, let session = self.session else { return }
            VTSessionSetProperty(session, key: kVTCompressionPropertyKey_ExpectedFrameRate, value: newFPS as CFTypeRef)
        }
    }

    fileprivate func handleEncodedFrame(_ sampleBuffer: CMSampleBuffer) {
        guard let dataBuffer = CMSampleBufferGetDataBuffer(sampleBuffer) else { return }

        let isKeyFrame: Bool = {
            guard let attachments = CMSampleBufferGetSampleAttachmentsArray(sampleBuffer, createIfNecessary: false) as? [[CFString: Any]],
                  let first = attachments.first else { return true }
            return !(first[kCMSampleAttachmentKey_NotSync] as? Bool ?? false)
        }()

        var length = 0
        var dataPointer: UnsafeMutablePointer<Int8>?
        CMBlockBufferGetDataPointer(dataBuffer, atOffset: 0, lengthAtOffsetOut: nil, totalLengthOut: &length, dataPointerOut: &dataPointer)

        guard let pointer = dataPointer, length > 0 else { return }

        var frameData = Data()

        // For keyframes, prepend VPS/SPS/PPS from the format description
        // so the decoder can create its decoding session.
        if isKeyFrame, let formatDesc = CMSampleBufferGetFormatDescription(sampleBuffer) {
            var paramCount: Int = 0
            CMVideoFormatDescriptionGetHEVCParameterSetAtIndex(formatDesc, parameterSetIndex: 0,
                parameterSetPointerOut: nil, parameterSetSizeOut: nil, parameterSetCountOut: &paramCount, nalUnitHeaderLengthOut: nil)

            for i in 0..<paramCount {
                var paramPtr: UnsafePointer<UInt8>?
                var paramSize: Int = 0
                let status = CMVideoFormatDescriptionGetHEVCParameterSetAtIndex(formatDesc, parameterSetIndex: i,
                    parameterSetPointerOut: &paramPtr, parameterSetSizeOut: &paramSize, parameterSetCountOut: nil, nalUnitHeaderLengthOut: nil)
                if status == noErr, let ptr = paramPtr, paramSize > 0 {
                    // Write 4-byte AVCC length prefix + parameter set data
                    var len = UInt32(paramSize).bigEndian
                    frameData.append(Data(bytes: &len, count: 4))
                    frameData.append(Data(bytes: ptr, count: paramSize))
                }
            }
        }

        frameData.append(Data(bytes: pointer, count: length))
        onEncodedFrame?(frameData, isKeyFrame)
    }
}

private func encoderCallback(outputCallbackRefCon: UnsafeMutableRawPointer?,
                              sourceFrameRefCon: UnsafeMutableRawPointer?,
                              status: OSStatus,
                              infoFlags: VTEncodeInfoFlags,
                              sampleBuffer: CMSampleBuffer?) {
    guard status == noErr, let sampleBuffer = sampleBuffer, let refcon = outputCallbackRefCon else { return }
    let encoder = Unmanaged<VideoEncoder>.fromOpaque(refcon).takeUnretainedValue()
    encoder.handleEncodedFrame(sampleBuffer)
}

import Foundation
import Network
import CoreMedia
import CoreGraphics

public class ServerCore {
    public static let shared = ServerCore()

    private let tcpChannel = TCPChannel()
    private let udpChannel = UDPChannel()
    private var frameSender: FrameSender?
    private var inputReceiver: InputReceiver?
    private let screenCapture = ScreenCapture()
    private var videoEncoder: VideoEncoder?
    private var hostname: String = ""
    public private(set) var isRunning = false
    private var isStreaming = AtomicBool(false)
    // Protects inputReceiver, frameSender, videoEncoder from concurrent access
    // between tcpChannel.onReceive (TCP queue) and startStreaming/stopStreaming (async context).
    private let stateQueue = DispatchQueue(label: "eclipticrd.server.state")

    private var heartbeatTimer: DispatchSourceTimer?
    private let heartbeatQueue = DispatchQueue(label: "eclipticrd.server.heartbeat")
    private var lastPongTime: Date = Date()
    private let pongLock = NSLock()

    private var clipboardMonitor: ClipboardMonitor?
    private var peerCapabilities: HandshakeCapabilities = []
    private var activeStreamConfig: StreamConfiguration?

    public var onRunningChanged: (@Sendable (Bool) -> Void)?

    private init() {}

    public func start(pin: String? = nil) async {
        hostname = ProcessInfo.processInfo.hostName

        do {
            // 1. Start TCP listener for control/input
            try tcpChannel.startListening(port: ERDConstants.tcpPort)
            isRunning = true
            onRunningChanged?(true)

            // 2. Start UDP listener for video frames
            try udpChannel.startListening(port: ERDConstants.udpPort)
            ERDLog.info("[Server] Listening on UDP:\(ERDConstants.udpPort)")

            // 3. Set up handlers BEFORE advertising/signaling so incoming connections are handled
            tcpChannel.onConnect = { [weak self] in
                ERDLog.info("[Server] Client connected!")
                Task { await self?.startStreaming() }
            }
            tcpChannel.onDisconnect = { [weak self] in
                ERDLog.info("[Server] Client disconnected")
                Task { await self?.stopStreaming() }
            }
            tcpChannel.onReceive = { [weak self] data in
                guard let self = self else { return }
                guard data.count >= ERDConstants.packetHeaderSize else { return }
                guard let header = PacketHeader.deserialize(from: data) else {
                    return
                }
                let payload = data.subdata(in: ERDConstants.packetHeaderSize..<data.count)

                switch header.type {
                case .inputEvent:
                    let receiver = self.stateQueue.sync { self.inputReceiver }
                    receiver?.handleInputEvent(payload)
                case .control:
                    if let msg = ControlMessage.deserialize(from: payload) {
                        switch msg.type {
                        case .requestKeyFrame:
                            let encoder = self.stateQueue.sync { self.videoEncoder }
                            encoder?.forceKeyFrame()
                        case .startStream: Task { await self.startStreaming() }
                        case .stopStream: Task { await self.stopStreaming() }
                        case .disconnect: Task { await self.stop() }
                        case .ping: break
                        case .streamConfigRequest:
                            if let data = msg.payload,
                               let req = StreamConfigurationRequestPayload.deserialize(from: data) {
                                Task { await self.handleStreamConfigRequest(req) }
                            }
                        case .streamConfigResponse, .streamConfigReject, .streamConfigError:
                            break // Server doesn't process these
                        case .clipboardSyncRequest:
                            break // Clipboard start/stop handled at session level
                        case .clipboardSyncUpdate:
                            if let data = msg.payload,
                               let update = ClipboardSyncUpdatePayload.deserialize(from: data) {
                                self.handleClipboardUpdate(update)
                            }
                        case .clipboardSyncError:
                            if let data = msg.payload,
                               let err = ClipboardSyncErrorPayload.deserialize(from: data) {
                                ERDLog.warning("[Server] Clipboard sync error from client: \(err.message)")
                            }
                        case .pong:
                            self.pongLock.lock()
                            self.lastPongTime = Date()
                            self.pongLock.unlock()
                        case .bitrateAdjust:
                            if let data = msg.payload,
                               let adj = BitrateAdjustPayload.deserialize(from: data) {
                                let newBitrate = Int(adj.targetBitrate)
                                ERDLog.info("[Server] Bitrate adjust request: \(newBitrate)")
                                let encoder = self.stateQueue.sync { self.videoEncoder }
                                encoder?.updateBitrate(newBitrate)
                            }
                        }
                    }
                case .handshake:
                    if let hs = HandshakePayload.deserialize(from: payload) {
                        ERDLog.info("[Server] Received handshake from client: \(hs.hostname) caps=\(hs.capabilities.rawValue)")
                        self.stateQueue.sync { self.peerCapabilities = hs.capabilities }
                        if self.isStreaming.value {
                            self.startClipboardSync()
                        }
                    }
                default: break
                }
            }

            // 4. Advertise via Bonjour (handlers are ready for incoming connections)
            tcpChannel.advertiseService(name: hostname)
            ERDLog.info("[Server] Advertising as '\(hostname)' via Bonjour")

            // 5. If PIN provided, exchange candidates via signaling
            if let pin = pin {
                await startSignaling(pin: pin)
            }

            ERDLog.info("[Server] Waiting for client connection...")
        } catch {
            isRunning = false
            onRunningChanged?(false)
            ERDLog.error("[Server] Fatal error: \(error)")
        }
    }

    private func startSignaling(pin: String) async {
        do {
            let stun = STUNClient()
            let (publicIP, publicPort) = try await stun.fetchPublicIP()
            ERDLog.info("[Server] STUN Public IP: \(publicIP):\(publicPort)")

            let localIP = NetworkUtils.getLocalIP() ?? "127.0.0.1"
            let signaling = SignalingClient(pin: pin, role: "server")
            let ourCandidate = SessionCandidate(role: "server", localIP: localIP, localPort: ERDConstants.tcpPort,
                                                  publicIP: publicIP, publicPort: publicPort)

            ERDLog.info("[Server] Exchanging candidates via PIN: \(pin)")
            let _ = try await signaling.exchangeCandidate(ourCandidate)
            signaling.stop()
            ERDLog.info("[Server] Signaling complete, waiting for client TCP connection...")
        } catch {
            ERDLog.error("[Server] Signaling failed: \(error)")
        }
    }

    private func startStreaming() async {
        guard !isStreaming.value else {
            return
        }

        guard CGPreflightScreenCaptureAccess() else {
            ERDLog.warning("[Server] Screen Recording permission not granted")
            ERDLog.warning("[Server]    Go to System Settings > Privacy & Security > Screen Recording")
            return
        }

        isStreaming.value = true

        let info = screenCapture.getDisplayInfo()
        let initialConfiguration = StreamConfiguration(
            width: UInt32(info.pixelWidth),
            height: UInt32(info.pixelHeight),
            bitrate: UInt32(ERDConstants.defaultBitrate),
            framesPerSecond: UInt16(ERDConstants.defaultFPS)
        )

        stateQueue.sync {
            inputReceiver = InputReceiver(screenWidth: CGFloat(info.width), screenHeight: CGFloat(info.height))
            frameSender = FrameSender(udpChannel: udpChannel)
            activeStreamConfig = initialConfiguration
        }

        // Send handshake to client (logical resolution for coordinate mapping)
        let handshake = HandshakePayload(hostname: hostname, screenWidth: UInt16(info.width),
                                          screenHeight: UInt16(info.height), scaleFactor: Float(info.scale),
                                          capabilities: [.streamConfiguration, .textClipboardSync])
        let header = PacketHeader(type: .handshakeAck, sequence: 0, timestamp: 0)
        var packet = header.serialize()
        packet.append(handshake.serialize())
        tcpChannel.send(packet)

        let preferredFPS = UserDefaults.standard.integer(forKey: "preferredFPS")
        let fps = preferredFPS > 0 ? preferredFPS : ERDConstants.defaultFPS

        // Setup pipeline: capture → encode → send (physical resolution for encoding)
        let encoder = makeVideoEncoder(
            width: info.pixelWidth,
            height: info.pixelHeight,
            bitrate: ERDConstants.defaultBitrate,
            fps: fps
        )

        stateQueue.sync { videoEncoder = encoder }

        screenCapture.onFrame = { [weak self] sampleBuffer in
            guard let self = self else { return }
            let encoder = self.stateQueue.sync { self.videoEncoder }
            encoder?.encode(sampleBuffer)
        }
        screenCapture.onCursorPosition = { [weak self] point in
            guard let self = self else { return }
            let nx = Float(point.x) / Float(info.width)
            let ny = Float(point.y) / Float(info.height)
            let sender = self.stateQueue.sync { self.frameSender }
            sender?.sendCursorUpdate(x: nx, y: ny)
        }
        screenCapture.onAudio = { [weak self] sampleBuffer in
            self?.handleAudioFrame(sampleBuffer)
        }

        do {
            try encoder.start()
            try await screenCapture.start(fps: fps)
            startHeartbeat()
            startClipboardSync()
            ERDLog.info("[Server] Streaming started: \(info.width)x\(info.height)")
        } catch {
            isStreaming.value = false
            stopHeartbeat()
            do { try await screenCapture.stop() } catch { }
            stateQueue.sync {
                videoEncoder?.stop()
                videoEncoder = nil
                frameSender = nil
                inputReceiver = nil
                activeStreamConfig = nil
            }
            ERDLog.error("[Server] Failed to start streaming: \(error)")
        }
    }

    private func stopStreaming() async {
        guard isStreaming.value else { return }
        isStreaming.value = false
        stopClipboardSync()
        stopHeartbeat()
        do { try await screenCapture.stop() } catch { ERDLog.error("[Server] Error stopping capture: \(error)") }

        stateQueue.sync {
            videoEncoder?.stop()
            videoEncoder = nil
            frameSender = nil
            inputReceiver = nil
            activeStreamConfig = nil
        }
        ERDLog.info("[Server] Streaming stopped")
    }

    public func stop() async {
        await stopStreaming()
        tcpChannel.stop()
        udpChannel.stop()
        isRunning = false
        onRunningChanged?(false)
    }

    // MARK: - Stream Configuration

    private func handleStreamConfigRequest(_ request: StreamConfigurationRequestPayload) async {
        let desired = request.desiredConfiguration

        // Validate requested dimensions
        let info = screenCapture.getDisplayInfo()
        let maxW = UInt32(info.pixelWidth)
        let maxH = UInt32(info.pixelHeight)

        if desired.width > maxW || desired.height > maxH || desired.width == 0 || desired.height == 0 {
            let reject = StreamConfigurationRejectPayload(
                requestID: request.requestID,
                reason: .unsupportedDimensions,
                message: "Dimensions must be 1..\(maxW)x\(maxH)")
            let msg = ControlMessage(type: .streamConfigReject, payload: reject.serialize())
            tcpChannel.sendControl(msg)
            return
        }

